text:
{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Kestrel Logistics Corp."],
   "quote": "by and between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Kestrel Logistics Corp. (\"Kestrel\")"
  },
  "counterparty": {
   "value": "Kestrel Logistics Corp.",
   "quote": "and Kestrel Logistics Corp. (\"Kestrel\")"
  },
  "effective_date": {
   "value": "2026-05-30",
   "quote": "is entered into as of 2026-05-30 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 12,
   "quote": "This Agreement will remain in effect for 1 year from the Effective Date."
  },
  "auto_renewal": {
   "value": true,
   "quote": "this Agreement shall automatically renew for successive one (1) year periods unless either Party provides written notice of non-renewal"
  },
  "renewal_notice_days": {
   "value": 60,
   "quote": "unless either Party provides written notice of non-renewal at least 60 days prior to the end of the then-current term"
  },
  "governing_law": {
   "value": "New York",
   "quote": "The laws of the State of New York govern this Agreement and any dispute arising out of it."
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  },
  "payment_terms_days": {
   "value": 90,
   "quote": "Northwind shall pay all undisputed invoices within ninety (90) days of receipt."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Samuel Okafor",
   "email": "samuel.okafor@kestrel.example",
   "title": "General Counsel",
   "party": "Kestrel Logistics Corp."
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_confidentiality_clause",
   "severity": "high",
   "message": "The agreement has no confidentiality obligations, so Northwind's information shared with Kestrel is not contractually protected.",
   "quote": "This Agreement constitutes the entire agreement between the Parties and supersedes all prior discussions relating to its subject matter."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "No right to terminate without cause or for breach is stated, and the agreement auto-renews, so Northwind could be locked into renewals unless it gives notice at least 60 days before term end.",
   "quote": "this Agreement shall automatically renew for successive one (1) year periods unless either Party provides written notice of non-renewal at least 60 days prior to the end of the then-current term."
  },
  {
   "id": "long_payment_terms",
   "severity": "low",
   "message": "Net-90 payment terms are favorable to Northwind for cash flow, but may prompt the vendor to push back or raise prices.",
   "quote": "Northwind shall pay all undisputed invoices within ninety (90) days of receipt."
  },
  {
   "id": "narrow_indemnity",
   "severity": "medium",
   "message": "Indemnification runs only from Kestrel to Northwind and is vaguely scoped to third-party claims arising from the Services, with no defense obligation or procedure. It is also subject to the liability cap, which has no carve-outs.",
   "quote": "Kestrel shall indemnify and hold harmless Northwind from third-party claims arising from the Services."
  },
  {
   "id": "fees_undefined",
   "severity": "medium",
   "message": "Fees are not defined in the MSA and depend entirely on future SOWs, so there is no pricing or spending cap at the master level. The liability cap depends on those fees.",
   "quote": "Fees for the Services are set out in each Statement of Work."
  },
  {
   "id": "mutual_cap_no_carveouts",
   "severity": "medium",
   "message": "The liability cap applies to both parties with no carve-outs for indemnity, confidentiality breach, or gross negligence, which limits Northwind's recovery from Kestrel.",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISK TO THE CLAIM."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a one-year Master Services Agreement between Northwind Labs, Inc. and Kestrel Logistics Corp., effective 2026-05-30. It auto-renews annually unless either party gives 60 days' notice, is governed by New York law, caps liability at 12 months of fees, and sets Net-90 payment, but it has no confidentiality clause and leaves pricing to future SOWs."
}
